-- MH-576 D7: a product is a blueprint a team turns into single-tenant instances. source_kind is
-- app|recipe|repo (where the blueprint came from: an existing app cloned, a catalog.KindStack
-- recipe, or a hand-entered repo); source_ref is that app's id, the recipe id, or "" for repo.
-- domain_suffix overrides the platform apps domain (internal/deploy/appsdomain.go) for this
-- product's instances; empty uses the platform's. env_defaults is non-secret defaults applied to
-- every new instance (secrets are set per instance, sealed like any other app env var).
CREATE UNIQUE INDEX products_team_name_key ON products (team_id, name);
CREATE INDEX products_team_idx ON products (team_id, created_at);
